def check_power_of_two(N):
    if N <= 0:
        return False
    return (N & (N - 1) == 0)

def solve_n5(X_max):
    solutions = []
    print(f"--- Searching for n=5 up to x={X_max} ---")
    for x in range(6, X_max + 1):
        lhs = x**5 + x - 2
        if check_power_of_two(lhs):
            k = lhs.bit_length() - 1
            solutions.append((x, 5, k))
            print(f"Solution found: x={x}, k={k}. LHS={lhs}")
        # Optimization: if lhs exceeds a large power of 2, we might stop early, but let's keep it simple for now.
    return solutions

# Test up to X=1000
solutions_n5 = solve_n5(1000)
print(f"\nTotal solutions found for n=5 up to x=1000: {len(solutions_n5)}")
